-- Tile the active year's wards with placeholder Muqaddam beats. Every row is
-- flagged is_synthetic so it can never pass for surveyed municipal data.
select public.generate_synthetic_zones();

-- Sanity: the delimitation must have loaded before anything depends on it.
do $$
declare n integer;
begin
  select count(*) into n from public.wards where year = public.active_ward_year();
  if n = 0 then
    raise exception 'no wards loaded for active year %', public.active_ward_year();
  end if;
  raise notice 'wards loaded: % for year %', n, public.active_ward_year();
end $$;
